<div class="wrap">
  <h1>Hitelkalkulátor</h1>
  <p class="sub">Add meg a hitelösszeget, az éves kamatot és a futamidőt – a kalkulátor kiszámolja a havi törlesztőt és a tőke–kamat bontást évek szerint.</p>

  <form class="card" id="form" novalidate>
    <div class="grid">
      <div>
        <label for="amount">Hitelösszeg</label>
        <div class="input-wrap">
          <input id="amount" type="number" inputmode="decimal" min="0" step="any" placeholder="pl. 10 000 000">
          <span class="suffix">Ft</span>
        </div>
      </div>
      <div>
        <label for="rate">Éves kamat</label>
        <div class="input-wrap">
          <input id="rate" type="number" inputmode="decimal" min="0" step="any" placeholder="pl. 6,5">
          <span class="suffix">%</span>
        </div>
      </div>
      <div>
        <label for="term">Futamidő</label>
        <div class="input-wrap">
          <input id="term" type="number" inputmode="numeric" min="1" step="1" placeholder="pl. 240">
          <span class="suffix">hónap</span>
        </div>
      </div>
    </div>
    <div class="actions">
      <button type="submit" class="primary">Számolás</button>
      <button type="button" id="reset">Alaphelyzet</button>
    </div>
  </form>

  <div id="status" class="sr" aria-live="polite"></div>
  <div id="result" style="margin-top:22px"></div>
</div>

<script>
(function () {
  var form = document.getElementById('form');
  var amountEl = document.getElementById('amount');
  var rateEl = document.getElementById('rate');
  var termEl = document.getElementById('term');
  var resetBtn = document.getElementById('reset');
  var resultEl = document.getElementById('result');
  var statusEl = document.getElementById('status');
  var STORE = 'loan-calc';

  function nf(n) { return Math.round(n).toLocaleString('hu-HU'); }
  function nf2(n) { return n.toLocaleString('hu-HU', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  function parseNum(el) {
    var v = el.value.trim().replace(/\s+/g, '').replace(',', '.');
    if (v === '') return NaN;
    var n = parseFloat(v);
    return isNaN(n) ? NaN : n;
  }

  function compute(P, annualPct, n) {
    var r = annualPct / 100 / 12;
    var payment;
    if (r === 0) {
      payment = P / n;
    } else {
      var f = Math.pow(1 + r, n);
      payment = P * r * f / (f - 1);
    }
    var balance = P, totalInt = 0, years = [];
    for (var m = 1; m <= n; m++) {
      var interest = balance * r;
      var principal = payment - interest;
      balance -= principal;
      totalInt += interest;
      var y = Math.ceil(m / 12);
      if (!years[y - 1]) years[y - 1] = { year: y, principal: 0, interest: 0, endBalance: 0 };
      years[y - 1].principal += principal;
      years[y - 1].interest += interest;
      years[y - 1].endBalance = balance;
    }
    return { payment: payment, total: payment * n, totalInt: totalInt, principalTotal: P, years: years };
  }

  function render(data) {
    if (!data) {
      resultEl.innerHTML =
        '<div class="empty"><div class="big">Még nincs számítás</div>' +
        'Töltsd ki a fenti mezőket, majd nyomd meg a „Számolás” gombot.</div>';
      return;
    }
    var capPct = Math.round(data.principalTotal / data.total * 100);
    var intPct = 100 - capPct;
    var rows = '';
    for (var i = 0; i < data.years.length; i++) {
      var y = data.years[i];
      rows += '<tr><td>' + y.year + '. év</td><td>' + nf(y.principal) + '</td><td>' +
        nf(y.interest) + '</td><td>' + nf(y.principal + y.interest) + '</td><td>' +
        nf(Math.max(0, y.endBalance)) + '</td></tr>';
    }
    resultEl.innerHTML =
      '<div class="stats">' +
        '<div class="stat accent"><div class="k">Havi törlesztő</div><div class="v">' + nf(data.payment) + ' Ft</div></div>' +
        '<div class="stat"><div class="k">Teljes visszafizetendő</div><div class="v">' + nf(data.total) + ' Ft</div></div>' +
        '<div class="stat"><div class="k">Összes kamat</div><div class="v">' + nf(data.totalInt) + ' Ft</div></div>' +
      '</div>' +
      '<div class="card" style="margin-top:16px">' +
        '<h3>A tőke és a kamat aránya</h3>' +
        '<div class="bar"><div class="cap" style="width:' + capPct + '%"></div><div class="int" style="width:' + intPct + '%"></div></div>' +
        '<div class="bar-legend">' +
          '<span><i class="dot cap"></i> Tőke ' + nf(data.principalTotal) + ' Ft (' + capPct + '%)</span>' +
          '<span><i class="dot int"></i> Kamat ' + nf(data.totalInt) + ' Ft (' + intPct + '%)</span>' +
        '</div>' +
      '</div>' +
      '<h2>Éves bontás</h2>' +
      '<div class="table-scroll"><table>' +
        '<caption>A tőke és a kamat évenkénti alakulása</caption>' +
        '<thead><tr><th>Év</th><th>Tőke (Ft)</th><th>Kamat (Ft)</th><th>Törlesztő (Ft)</th><th>Fennmaradó (Ft)</th></tr></thead>' +
        '<tbody>' + rows + '</tbody>' +
        '<tfoot><tr><td>Összesen</td><td>' + nf(data.principalTotal) + '</td><td>' + nf(data.totalInt) +
          '</td><td>' + nf(data.total) + '</td><td>0</td></tr></tfoot>' +
      '</table></div>';
  }

  function show() {
    var P = parseNum(amountEl), annual = parseNum(rateEl), n = parseNum(termEl);
    if (!(P > 0) || isNaN(annual) || annual < 0 || !(n >= 1) || n % 1 !== 0) {
      statusEl.textContent = 'Kérlek, adj meg érvényes értékeket.';
      render(null);
      return;
    }
    var data = compute(P, annual, n);
    render(data);
    statusEl.textContent = 'Számítás kész: havi törlesztő ' + nf(data.payment) + ' forint.';
    persist();
  }

  var persistTimer = null;
  function persist() {
    if (!(window.alfy && window.alfy.storage)) return;
    clearTimeout(persistTimer);
    persistTimer = setTimeout(function () {
      window.alfy.storage.set(STORE, {
        amount: amountEl.value, rate: rateEl.value, term: termEl.value
      });
    }, 200);
  }

  form.addEventListener('submit', function (e) { e.preventDefault(); show(); });
  [amountEl, rateEl, termEl].forEach(function (el) {
    el.addEventListener('input', function () { persist(); show(); });
  });
  resetBtn.addEventListener('click', function () {
    amountEl.value = ''; rateEl.value = ''; termEl.value = '';
    persist();
    render(null);
    statusEl.textContent = 'Mezők törölve.';
    amountEl.focus();
  });

  function init() {
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.get(STORE).then(function (saved) {
        if (saved) {
          amountEl.value = saved.amount || '';
          rateEl.value = saved.rate || '';
          termEl.value = saved.term || '';
          show();
        } else {
          render(null);
        }
      }).catch(function () { render(null); });
    } else {
      render(null);
    }
  }
  init();
})();
</script>
